insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, operator) values ('the-french-house', 'The French House', '49 Dean Street, Soho, London W1D 5BG', 'Soho', 51.51323, -0.13178, 1891, array['historic', 'no-music-no-tv']::text[], 'A tiny Soho institution with a Free French wartime connection. It traditionally pours beer in halves only, and has no music, TVs or phones.', 'https://www.frenchhousesoho.com/', null, 'Independent') on conflict (id) do update set website = coalesce(public.pubs.website, excluded.website), drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url), operator = coalesce(public.pubs.operator, excluded.operator);
